C is the strongest candidate for the original checkpoint: the changes from C to A and C to B are nearly orthogonal, as expected for two separate fine-tunes. B also differs substantially more from C than A does.

I’ll check whether this pattern is consistent across blocks and inspect the attention key biases. These biases cancel out of attention softmax in exact arithmetic, so they can sometimes reveal weight decay more directly than task-driven learning.
```python
print("Changes relative to C: relative Frobenius norm (%)")
print("block part       A/C     B/C    B/A delta ratio   delta cosine")
for block in range(4,8):
    for part in ["q","k","v","out","fc1","fc2"]:
        if part in ["q","k","v"]:
            sl = {"q":slice(0,768),"k":slice(768,1536),"v":slice(1536,2304)}[part]
            arr = {m:weights[m][f"block{block}.attn.in_proj_weight"][sl].astype(np.float64) for m in labels}
        else:
            suffix = {"out":"attn.out_proj.weight", "fc1":"mlp.fc1.weight", "fc2":"mlp.fc2.weight"}[part]
            arr = {m:weights[m][f"block{block}.{suffix}"].astype(np.float64) for m in labels}
        da,db = arr["A"]-arr["C"], arr["B"]-arr["C"]
        na,nb,nc = np.linalg.norm(da),np.linalg.norm(db),np.linalg.norm(arr["C"])
        co = np.sum(da*db)/(na*nb)
        print(block, f"{part:4s}", f"{100*na/nc:8.3f} {100*nb/nc:8.3f} {nb/na:9.4f} {co:12.4f}")

print("\nQ/K/V bias norms (A B C)")
for block in range(4,8):
    for i,part in enumerate(["q","k","v"]):
        arr = {m:weights[m][f"block{block}.attn.in_proj_bias"][i*768:(i+1)*768].astype(np.float64) for m in labels}
        print(block, part, " ".join(f"{np.linalg.norm(arr[m]):.9g}" for m in labels))
        if part == "k":
            for m in ["A","B"]:
                c,x=arr["C"],arr[m]
                scale=np.dot(x,c)/np.dot(c,c)
                residual=np.linalg.norm(x-scale*c)/np.linalg.norm(c)
                print(" ",m,"vs C: scale",round(scale,8),"relative residual",round(residual,8))

print("\nBlock aggregate changes from C")
for block in range(4,8):
    bk=[k for k in keys if k.startswith(f"block{block}.")]
    nc=sum(np.sum(weights["C"][k].astype(np.float64)**2) for k in bk)**0.5
    vals=[]
    for m in ["A","B"]:
        nd=sum(np.sum((weights[m][k].astype(np.float64)-weights["C"][k])**2) for k in bk)**0.5
        vals.append(nd)
    print(block, "delta A/B",*[round(v,5) for v in vals],"relative %",*[round(100*v/nc,3) for v in vals])
```
